(()=>{'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),overlay=$('#overlay');
const screens=['title-screen','level-screen','pause-screen','end-screen','armory-screen'].map(id=>$('#'+id));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const SAVE_KEY='gloamward-save-v1';
const freshSave=()=>({shards:0,best:0,runs:0,upgrades:{vitality:0,edge:0,haste:0,boots:0,magnet:0}});
let save;try{save={...freshSave(),...JSON.parse(localStorage.getItem(SAVE_KEY)||'{}')};save.upgrades={...freshSave().upgrades,...(save.upgrades||{})}}catch{save=freshSave()}
function persist(){localStorage.setItem(SAVE_KEY,JSON.stringify(save));updateMeta()}
const metaDefs=[
 {id:'vitality',icon:'♥',name:'HEARTWOOD',desc:'Begin each run with +20 maximum health.',base:25},
 {id:'edge',icon:'⚔',name:'SHARPENED IRON',desc:'Deal +10% damage with every weapon.',base:30},
 {id:'haste',icon:'✦',name:'QUICKENED HAND',desc:'Attack 8% faster per blessing.',base:35},
 {id:'boots',icon:'⌁',name:'WINDSTITCH BOOTS',desc:'Move 7% faster with every blessing.',base:25},
 {id:'magnet',icon:'◉',name:'GRAVITY WELL',desc:'Gather shards and essence from farther away.',base:30}
];
let W=innerWidth,H=innerHeight,dpr=1,screen='title',last=0,elapsed=0,runShards=0,kills=0,level=1,xp=0,xpNeed=12,spawnClock=0,attackClock=0,enemySerial=0,bossActive=false,bossSpawned=false,damageFlash=0,shake=0;
let player=null,enemies=[],shots=[],gems=[],particles=[],orbs=[],decor=[];
const keys=new Set(),input={x:0,y:0,touch:false};
function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
addEventListener('resize',resize);resize();
function showOnly(name){screens.forEach(s=>s.classList.toggle('hidden',s.id!==name));overlay.style.display=name?'grid':'none'}
function updateMeta(){$('#bank-shards').textContent=save.shards;$('#best-time').textContent=save.best?fmt(save.best):'—'}
function fmt(t){let m=Math.floor(t/60),s=Math.floor(t%60);return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function updateHUD(){if(!player)return;$('#timer').textContent=fmt(elapsed);$('#wave-label').textContent='NIGHT '+String(Math.floor(elapsed/60)+1).padStart(2,'0');$('#kill-label').textContent=kills+' FALLEN';$('#hp-fill').style.width=(100*clamp(player.hp/player.maxHp,0,1))+'%';$('#hp-text').textContent=Math.ceil(player.hp)+' / '+player.maxHp;$('#xp-fill').style.width=(100*xp/xpNeed)+'%';$('#level-text').textContent='LV '+level;$('#run-coins').textContent=runShards}
function initRun(){elapsed=0;runShards=0;kills=0;level=1;xp=0;xpNeed=12;spawnClock=1;attackClock=.35;enemySerial=0;bossActive=false;bossSpawned=false;damageFlash=0;shake=0;enemies=[];shots=[];gems=[];particles=[];orbs=[];const up=save.upgrades;let hp=100+(up.vitality||0)*20;player={x:0,y:0,vx:0,vy:0,r:14,hp,maxHp:hp,damage:14*(1+(up.edge||0)*.10),rate:.78/(1+(up.haste||0)*.08),speed:205*(1+(up.boots||0)*.07),magnet:105+(up.magnet||0)*30,regen:0,armor:0,crit:0,projectiles:1,pierce:0,orbCount:0,orbitDamage:13,thorns:0,dash:0,dashCd:0,invuln:0,walk:0};for(let i=0;i<36;i++)decor.push({x:rand(-1400,1400),y:rand(-1000,1000),r:rand(1,3),a:rand(.06,.25)});$('#hud').classList.remove('hidden');$('#mobile-controls').classList.toggle('hidden',matchMedia('(min-width:701px)').matches);$('#boss-hud').classList.add('hidden');showOnly(null);screen='run';updateHUD();last=performance.now()}
function startRun(){initRun();requestAnimationFrame(frame)}
function endRun(reason='fall'){if(screen!=='run')return;screen='end';$('#hud').classList.add('hidden');$('#mobile-controls').classList.add('hidden');$('#boss-hud').classList.add('hidden');save.shards+=runShards;save.runs++;save.best=Math.max(save.best,Math.floor(elapsed));persist();$('#end-time').textContent=fmt(elapsed);$('#end-kills').textContent=kills;$('#end-shards').textContent=runShards;$('#end-title').innerHTML=reason==='dawn'?'DAWN FINDS<br><em>YOU ALIVE.</em>':'YOU HELD<br><em>THE LINE.</em>';$('#end-copy').textContent=reason==='dawn'?'A whole night survived. The valley remembers.':'The valley remembers every second you stole.';showOnly('end-screen')}
function pause(){if(screen!=='run')return;screen='pause';showOnly('pause-screen')}
function resume(){if(screen!=='pause')return;screen='run';showOnly(null);last=performance.now();requestAnimationFrame(frame)}
function randEdge(){let a=rand(0,Math.PI*2),d=Math.max(W,H)*.65+rand(20,190);return{x:player.x+Math.cos(a)*d,y:player.y+Math.sin(a)*d}}
function spawnEnemy(type){let p=randEdge(),n=elapsed/60;let e={x:p.x,y:p.y,vx:0,vy:0,r:13,hp:28+n*5,speed:38+n*1.1,damage:10+n*.35,color:'#bf7062',type:'wisp',xp:3,hit:0,attack:0,id:++enemySerial};let r=Math.random();if(type==='boss'){e={...e,type:'boss',r:31,hp:600+elapsed*2.7,speed:24+elapsed*.025,damage:22,xp:80,color:'#9d6158',attack:1.6,hit:0,id:enemySerial,shardDrop:22};bossActive=true;$('#boss-hud').classList.remove('hidden')}else if(elapsed>45&&r<.18){e.type='brute';e.r=20;e.hp*=3.2;e.speed*=.65;e.damage*=1.6;e.xp=8;e.color='#cf8762'}else if(elapsed>100&&r<.3){e.type='stalker';e.r=10;e.hp*=.68;e.speed*=1.65;e.damage*=.82;e.xp=4;e.color='#b9a67c'}enemies.push(e);return e}
const upgradePool=[
 {id:'might',icon:'⚔',name:'HEAVIER BLOWS',desc:'Your weapons deal 25% more damage.',tag:'DAMAGE',apply:()=>player.damage*=1.25},
 {id:'tempo',icon:'✦',name:'QUICKEN THE RHYTHM',desc:'Attack 20% faster. Let the steel sing.',tag:'ATTACK SPEED',apply:()=>player.rate*=.8},
 {id:'fleet',icon:'⌁',name:'GHOSTSTEP',desc:'Move 15% faster through the dark.',tag:'MOVEMENT',apply:()=>player.speed*=1.15},
 {id:'heart',icon:'♥',name:'SECOND WIND',desc:'Restore 35 health and gain 15 max health.',tag:'VITALITY',apply:()=>{player.maxHp+=15;player.hp=Math.min(player.maxHp,player.hp+35)}},
 {id:'reach',icon:'◉',name:'GRAVITY WELL',desc:'Pull in essence and shards from 40% farther.',tag:'GATHER',apply:()=>player.magnet*=1.4},
 {id:'double',icon:'✺',name:'TWIN FLAME',desc:'Fire an additional projectile each volley.',tag:'PROJECTILE',apply:()=>player.projectiles=Math.min(5,player.projectiles+1)},
 {id:'pierce',icon:'➶',name:'PIERCING LIGHT',desc:'Projectiles pass through one more foe.',tag:'PIERCE',apply:()=>player.pierce++},
 {id:'orbit',icon:'✳',name:'WARDING STAR',desc:'A blade circles you, striking nearby enemies.',tag:'NEW WEAPON',apply:()=>{player.orbCount=Math.min(5,player.orbCount+1);orbs.push({phase:rand(0,6.28)})}},
 {id:'armor',icon:'⬟',name:'IRONBARK',desc:'Reduce incoming damage by 15%.',tag:'DEFENSE',apply:()=>player.armor=Math.min(.6,player.armor+.15)},
 {id:'regen',icon:'＋',name:'GREENBLOOD',desc:'Recover 1 health every second.',tag:'REGEN',apply:()=>player.regen+=1},
 {id:'critical',icon:'✧',name:'TRUE AIM',desc:'Gain 12% chance to deal double damage.',tag:'CRITICAL',apply:()=>player.crit=Math.min(.6,player.crit+.12)},
 {id:'thorns',icon:'❋',name:'THORNMAIL',desc:'Nearby enemies take damage when they strike you.',tag:'DEFENSE',apply:()=>player.thorns+=8}
];
function levelUp(){if(screen!=='run')return;screen='level';let choices=[...upgradePool].sort(()=>Math.random()-.5).slice(0,3);let box=$('#upgrade-cards');box.innerHTML='';for(const u of choices){let card=document.createElement('button');card.className='upgrade-card';card.innerHTML=`<span class="card-icon">${u.icon}</span><h3>${u.name}</h3><p>${u.desc}</p><small class="card-tag">${u.tag}</small>`;card.onclick=()=>{u.apply();screen='run';showOnly(null);last=performance.now();toast(u.name+' ACQUIRED');requestAnimationFrame(frame)};box.append(card)}showOnly('level-screen')}
function awardXP(amount){xp+=amount;while(xp>=xpNeed){xp-=xpNeed;level++;xpNeed=Math.floor(xpNeed*1.24+5);levelUp();break}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),1500)}

function damageEnemy(e,amount){if(e.hp<=0)return;e.hp-=amount;e.hit=.12;if(e.type==='boss')$('#boss-fill').style.width=(100*clamp(e.hp/(600+elapsed*2.7),0,1))+'%';if(e.hp<=0){kills++;if(e.type==='boss'){bossActive=false;$('#boss-hud').classList.add('hidden');runShards+=e.shardDrop||22;toast('WARDEN FALLEN · +22 SHARDS');for(let i=0;i<8;i++)gems.push({x:e.x+rand(-30,30),y:e.y+rand(-30,30),type:'xp',value:15,r:6})}else if(Math.random()<.14)gems.push({x:e.x,y:e.y,type:'shard',value:e.type==='brute'?3:1,r:6});gems.push({x:e.x,y:e.y,type:'xp',value:e.xp,r:5});burst(e.x,e.y,e.color,e.type==='boss'?30:7)}}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=rand(0,6.28),s=rand(25,150);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.2,.65),max:.65,color,r:rand(1,3)})}}
function nearest(){let best=null,bd=Infinity;for(const e of enemies)if(e.hp>0){let d=(e.x-player.x)**2+(e.y-player.y)**2;if(d<bd){bd=d;best=e}}return best}
function fire(){let target=nearest();if(!target)return;let a=Math.atan2(target.y-player.y,target.x-player.x);for(let i=0;i<player.projectiles;i++){let spread=(i-(player.projectiles-1)/2)*.13,ang=a+spread;shots.push({x:player.x+Math.cos(ang)*15,y:player.y+Math.sin(ang)*15,vx:Math.cos(ang)*480,vy:Math.sin(ang)*480,life:1.55,damage:player.damage*(Math.random()<player.crit?2:1),pierce:player.pierce,hit:new Set(),r:4})}burst(player.x+Math.cos(a)*14,player.y+Math.sin(a)*14,'#f2d18a',2)}
function tryDash(){if(!player||screen!=='run'||player.dashCd>0)return;let dx=input.x,dy=input.y;if(Math.hypot(dx,dy)<.1){let e=nearest();if(e){dx=player.x-e.x;dy=player.y-e.y}else dx=1}let m=Math.hypot(dx,dy)||1;player.vx=dx/m*760;player.vy=dy/m*760;player.dash=.17;player.dashCd=2.3;player.invuln=.38;burst(player.x,player.y,'#9ed6a3',8)}
function frame(now){if(screen!=='run')return;let dt=Math.min(.034,(now-last)/1000||.016);last=now;update(dt);draw();requestAnimationFrame(frame)}
function update(dt){elapsed+=dt;damageFlash=Math.max(0,damageFlash-dt);shake=Math.max(0,shake-dt*20);player.walk+=dt*10;player.invuln=Math.max(0,player.invuln-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.hp=Math.min(player.maxHp,player.hp+player.regen*dt);
 let kx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),ky=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0);let ix=input.touch?input.x:kx,iy=input.touch?input.y:ky,m=Math.hypot(ix,iy);if(m>1){ix/=m;iy/=m}if(player.dash>0){player.dash-=dt;player.x+=player.vx*dt;player.y+=player.vy*dt}else{player.vx+=(ix*player.speed-player.vx)*Math.min(1,dt*13);player.vy+=(iy*player.speed-player.vy)*Math.min(1,dt*13);player.x+=player.vx*dt;player.y+=player.vy*dt}
 attackClock-=dt;if(attackClock<=0){fire();attackClock+=player.rate}spawnClock-=dt;let spawnRate=Math.min(3.9,.75+elapsed/150);if(spawnClock<=0&&enemies.length<100){spawnEnemy();if(elapsed>80&&Math.random()<.25)spawnEnemy();spawnClock=1/spawnRate}if(elapsed>=90&&Math.floor(elapsed/120)>Math.floor((elapsed-dt)/120)&&!bossActive){spawnEnemy('boss');bossSpawned=true;toast('THE WARDEN HAS FOUND YOU')}
 for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];if(e.hp<=0){enemies.splice(i,1);continue}e.hit=Math.max(0,e.hit-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;e.attack-=dt;if(d<e.r+player.r+2&&e.attack<=0){if(player.invuln<=0){let dmg=Math.max(1,e.damage*(1-player.armor));player.hp-=dmg;player.invuln=.6;damageFlash=.18;shake=5;if(player.thorns)damageEnemy(e,player.thorns);burst(player.x,player.y,'#da8270',6);if(player.hp<=0){player.hp=0;updateHUD();endRun();return}}e.attack=e.type==='boss'?.65:.8}if(e.type==='boss'&&d>100&&d<430&&e.attack<.3){let a=Math.atan2(dy,dx);shots.push({x:e.x,y:e.y,vx:Math.cos(a)*185,vy:Math.sin(a)*185,life:3,damage:13+elapsed*.025,pierce:0,hit:new Set(),r:7,enemyShot:true});e.attack=1.6}}
 for(let i=shots.length-1;i>=0;i--){let s=shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.enemyShot){if(Math.hypot(s.x-player.x,s.y-player.y)<player.r+s.r&&player.invuln<=0){player.hp-=s.damage;player.invuln=.55;damageFlash=.18;shots.splice(i,1);continue}}else{for(let e of enemies){if(e.hp>0&&!s.hit.has(e.id)&&Math.hypot(s.x-e.x,s.y-e.y)<e.r+s.r){s.hit.add(e.id);damageEnemy(e,s.damage);if(s.pierce>0)s.pierce--;else{s.life=0;break}}}}if(s.life<=0)shots.splice(i,1)}
 for(let i=gems.length-1;i>=0;i--){let g=gems[i],d=Math.hypot(player.x-g.x,player.y-g.y);if(d<player.magnet){let f=clamp((1-d/player.magnet)*8,.8,7);g.x+=(player.x-g.x)*f*dt;g.y+=(player.y-g.y)*f*dt}if(d<player.r+g.r+5){if(g.type==='shard'){runShards+=g.value;burst(g.x,g.y,'#e5b866',5)}else awardXP(g.value);gems.splice(i,1)}}
 for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;p.life-=dt}particles=particles.filter(p=>p.life>0);if(player.orbCount){for(let i=0;i<player.orbCount;i++){let a=elapsed*1.6+i*Math.PI*2/player.orbCount,ox=player.x+Math.cos(a)*48,oy=player.y+Math.sin(a)*48;for(let e of enemies)if(Math.hypot(e.x-ox,e.y-oy)<e.r+9)e._orbHit=(e._orbHit||0)-dt;if(e._orbHit<0){damageEnemy(e,player.orbitDamage);e._orbHit=.35}}}
 if(elapsed>15&&Math.floor(elapsed)%60===0&&Math.floor(elapsed)!==Math.floor(elapsed-dt)){runShards+=5;toast('NIGHT SURVIVED · +5 SHARDS')}if(elapsed>=900){endRun('dawn');return}if(bossActive){let boss=enemies.find(e=>e.type==='boss'&&e.hp>0);if(boss)$('#boss-fill').style.width=(100*clamp(boss.hp/(600+elapsed*2.7),0,1))+'%'}updateHUD();$('#dash-btn').classList.toggle('cooldown',player.dashCd>0)}

