function hash(x,y){let n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);let camX=player?player.x:Math.sin(performance.now()*.00012)*110,camY=player?player.y:Math.cos(performance.now()*.00015)*65;ctx.fillStyle='#18221d';ctx.fillRect(0,0,W,H);let ox=W/2-camX+(shake?rand(-shake,shake):0),oy=H/2-camY+(shake?rand(-shake,shake):0);ctx.save();ctx.translate(ox,oy);
 const cell=128,x0=Math.floor((camX-W/2)/cell)-1,x1=Math.ceil((camX+W/2)/cell)+1,y0=Math.floor((camY-H/2)/cell)-1,y1=Math.ceil((camY+H/2)/cell)+1;
 for(let tx=x0;tx<=x1;tx++)for(let ty=y0;ty<=y1;ty++){let h=hash(tx,ty),x=tx*cell,y=ty*cell;ctx.fillStyle=h>.5?'rgba(45,64,50,.12)':'rgba(8,15,12,.14)';ctx.fillRect(x,y,cell,cell);let count=4+Math.floor(hash(tx+4,ty+1)*8);for(let n=0;n<count;n++){let px=x+hash(tx*7+n,ty*9+n)*cell,py=y+hash(tx*13+n,ty*5+n)*cell;ctx.fillStyle=`rgba(${hash(tx+n,ty)*50+45|0},${hash(tx,ty+n)*65+65|0},${hash(tx+n*3,ty+n)*42+48|0},${.14+hash(tx+n,ty+n)*.25})`;ctx.beginPath();ctx.ellipse(px,py,1+hash(tx+n*2,ty)*3,1+hash(tx,ty+n*2)*2,hash(tx+n,ty+n)*3,0,6.28);ctx.fill()}if(hash(tx,ty+17)>.87){let px=x+hash(tx+8,ty+2)*cell,py=y+hash(tx+2,ty+8)*cell;ctx.strokeStyle='rgba(10,16,12,.55)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(px+9,py+5);ctx.lineTo(px+13,py+14);ctx.moveTo(px+8,py+5);ctx.lineTo(px+1,py+11);ctx.stroke();ctx.fillStyle='rgba(112,126,82,.28)';ctx.beginPath();ctx.ellipse(px+17,py+13,5,2,.8,0,6.28);ctx.fill()}}
 // Pools of cold light drift through the forest floor.
 for(let i=0;i<5;i++){let px=camX+Math.sin(elapsed*.11+i*2.7)*W*.38,py=camY+Math.cos(elapsed*.09+i*1.9)*H*.38,g=ctx.createRadialGradient(px,py,0,px,py,150);g.addColorStop(0,'rgba(110,157,126,.055)');g.addColorStop(1,'rgba(110,157,126,0)');ctx.fillStyle=g;ctx.fillRect(px-150,py-150,300,300)}
 if(player){for(const e of enemies)drawEnemy(e);for(const g of gems){let glow=ctx.createRadialGradient(g.x,g.y,0,g.x,g.y,g.r*3.5);glow.addColorStop(0,g.type==='shard'?'rgba(229,184,102,.36)':'rgba(137,207,167,.3)');glow.addColorStop(1,'transparent');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(g.x,g.y,g.r*3.5,0,6.28);ctx.fill();ctx.save();ctx.translate(g.x,g.y);ctx.rotate(Math.PI/4);ctx.fillStyle=g.type==='shard'?'#e7bd72':'#a7d8b2';ctx.fillRect(-g.r*.65,-g.r*.65,g.r*1.3,g.r*1.3);ctx.restore()}
 for(const s of shots){ctx.save();ctx.shadowBlur=s.enemyShot?18:13;ctx.shadowColor=s.enemyShot?'#da755e':'#f6d58f';ctx.fillStyle=s.enemyShot?'#df8067':'#ffe6a9';ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,6.28);ctx.fill();ctx.restore()}
